package warungaju;

import java.awt.*;
import java.text.NumberFormat;
import java.util.Locale;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableCellRenderer;
import javax.swing.table.JTableHeader;

class UI {
    static void initTheme(){UIManager.put("Component.arc",14);UIManager.put("Button.arc",12);UIManager.put("TextComponent.arc",10);UIManager.put("Component.focusWidth",1);UIManager.put("Component.innerFocusWidth",0);UIManager.put("ScrollBar.width",10);UIManager.put("Button.font",new Font("SansSerif",Font.BOLD,13));UIManager.put("Button.background",new Color(235,242,239));UIManager.put("Button.foreground",MainFrame.TEXT);UIManager.put("Button.borderWidth",0);UIManager.put("Table.font",new Font("SansSerif",Font.PLAIN,13));UIManager.put("Table.foreground",MainFrame.TEXT);UIManager.put("Table.selectionBackground",new Color(205,232,221));UIManager.put("Table.selectionForeground",MainFrame.TEXT);UIManager.put("Table.rowHeight",32);UIManager.put("Table.showHorizontalLines",false);UIManager.put("Table.showVerticalLines",false);UIManager.put("TabbedPane.selected",new Color(224,241,234));UIManager.put("TabbedPane.tabHeight",38);}
    static JPanel page(String title,String subtitle){JPanel p=new JPanel(new BorderLayout(0,18)); p.setBackground(MainFrame.LIGHT); p.setBorder(new EmptyBorder(28,32,32,32)); JLabel h=new JLabel("<html><h1 style='margin:0'>"+title+"</h1><font color='#60736b'>"+subtitle+"</font></html>"); h.setFont(new Font("SansSerif",Font.PLAIN,14)); p.add(h,BorderLayout.NORTH); return p;}
    static JPanel card(String title,String value,Color color){JPanel p=new JPanel(new BorderLayout(8,8)); p.setBackground(Color.WHITE); p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(225,232,229)),new EmptyBorder(18,20,18,20))); JLabel a=new JLabel(title.toUpperCase()); a.setForeground(new Color(100,115,108)); a.setFont(new Font("SansSerif",Font.BOLD,11)); JLabel b=new JLabel(value); b.setFont(new Font("SansSerif",Font.BOLD,22)); b.setForeground(color); p.add(a,BorderLayout.NORTH); p.add(b,BorderLayout.CENTER); return p;}
    static String money(double n){return NumberFormat.getCurrencyInstance(new Locale("id","ID")).format(n).replace(",00","");}
    static JButton button(String text){JButton b=new JButton(text); b.setBackground(MainFrame.GREEN); b.setForeground(Color.WHITE); b.setFocusPainted(false); b.setBorder(BorderFactory.createEmptyBorder(10,18,10,18)); b.setCursor(new Cursor(Cursor.HAND_CURSOR)); addHover(b,MainFrame.GREEN,new Color(35,119,89)); return b;}
    static JButton navButton(String text){JButton b=button(text); b.setBackground(MainFrame.GREEN); b.setBorder(BorderFactory.createEmptyBorder(10,15,10,8)); b.setHorizontalAlignment(SwingConstants.LEFT); addHover(b,MainFrame.GREEN,new Color(35,119,89)); return b;}
    static JButton secondaryButton(String text){JButton b=new JButton(text); b.setFocusPainted(false); b.setBorder(BorderFactory.createEmptyBorder(10,16,10,16)); b.setCursor(new Cursor(Cursor.HAND_CURSOR)); addHover(b,new Color(235,242,239),new Color(216,231,224)); return b;}
    static void addHover(final JButton button,final Color normal,final Color hover){button.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseEntered(java.awt.event.MouseEvent e){button.setBackground(hover);}public void mouseExited(java.awt.event.MouseEvent e){if(!Boolean.TRUE.equals(button.getClientProperty("warungaju.active")))button.setBackground(normal);}});}
    static JPanel formGrid(){JPanel p=new JPanel(new GridBagLayout()); p.setBackground(Color.WHITE); return p;}
    static void field(JPanel p,GridBagConstraints g,String label,JComponent component,int row){g.gridx=0;g.gridy=row;g.weightx=0;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(8,8,8,16);p.add(new JLabel(label),g);g.gridx=1;g.weightx=1;g.insets=new Insets(8,8,8,8);p.add(component,g);}
    static JTextField input(String value){JTextField field=new JTextField(value); field.setPreferredSize(new Dimension(150,38)); field.setBorder(BorderFactory.createEmptyBorder(8,12,8,12)); return field;}
    static void styleTable(JTable table){table.setRowHeight(42); table.setShowVerticalLines(false); table.setShowHorizontalLines(true); table.setGridColor(new Color(232,238,235)); table.setIntercellSpacing(new Dimension(0,1)); table.setSelectionBackground(new Color(211,237,226)); table.setSelectionForeground(MainFrame.TEXT); table.setFillsViewportHeight(true); table.setDefaultRenderer(Object.class,new StripeRenderer()); JTableHeader header=table.getTableHeader(); header.setPreferredSize(new Dimension(0,42)); header.setReorderingAllowed(false); header.setFont(new Font("SansSerif",Font.BOLD,12)); header.setBackground(new Color(232,241,236)); header.setForeground(MainFrame.TEXT);}
    static JPanel searchBar(JTextField search,String hint){JPanel p=new JPanel(new BorderLayout(10,0));p.setOpaque(false);JLabel icon=new JLabel("⌕");icon.setFont(new Font("SansSerif",Font.BOLD,20));icon.setForeground(new Color(100,120,110));search.putClientProperty("JTextField.placeholderText",hint);p.add(icon,BorderLayout.WEST);p.add(search,BorderLayout.CENTER);return p;}
    static class StripeRenderer extends DefaultTableCellRenderer { public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focused,int row,int column){Component c=super.getTableCellRendererComponent(table,value,selected,focused,row,column);setBorder(BorderFactory.createEmptyBorder(0,12,0,12));setHorizontalAlignment(value instanceof Number?SwingConstants.RIGHT:SwingConstants.LEFT);if(!selected)c.setBackground(row%2==0?Color.WHITE:new Color(249,252,250));return c;}}
}
